-- 굿즈 OPTION-same-price 7상품 형상/방향 CPQ (2026-07-04)
-- 가격동일→공식/단가행 없음. 자재보유=ref→mat(유지)·미보유=siz mint+ref→siz.
\set ON_ERROR_STOP on
BEGIN;

-- ===== PRD_000188 레더코스터 (형상·2) =====

-- ===== PRD_000190 우드코스터 (형상·2) =====

-- ===== PRD_000192 규조토코스터 (형상·2) =====

-- ===== PRD_000267 린넨 에코백 (방향·2) =====

-- ===== PRD_000208 슬로건 (방향·2) =====

-- ===== PRD_000221 말랑키링 (형상·5) =====

-- ===== PRD_000242 광목 스트링 라벨파우치 (규격·2) =====

\echo '=== POST: 7상품 CPQ 요약 ==='
SELECT (SELECT count(*) FROM t_prd_product_option_groups WHERE prd_cd IN ('PRD_000188','PRD_000190','PRD_000192','PRD_000267','PRD_000208','PRD_000221','PRD_000242') AND del_yn='N') grps, (SELECT count(*) FROM t_prd_product_option_items WHERE prd_cd IN ('PRD_000188','PRD_000190','PRD_000192','PRD_000267','PRD_000208','PRD_000221','PRD_000242') AND del_yn='N') items, (SELECT count(*) FROM t_prd_product_prices WHERE prd_cd IN ('PRD_000188','PRD_000190','PRD_000192','PRD_000267','PRD_000208','PRD_000221','PRD_000242')) dprice;
ROLLBACK;